+        ".page-header",
+        ".card",
+        ".table-wrap",
+        "form.filters",
+        ".badge",
+        ":focus-visible",
+        "@media (prefers-color-scheme: dark)",
+        "@media (max-width: 900px)",
+        "data-dashboard-partial",
+        "data-poll-url",
